exec(open("tam.py").read().split("\nwith sync_playwright()")[0])
B8766='http://localhost:8766/'
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox','--headless=new','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'])
    ctx=b.new_context(viewport={'width':412,'height':915});pg=ctx.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto(B8766+'become-studio/index.html');pg.wait_for_timeout(2500)
    prod=pg.evaluate("""async()=>{localStorage.setItem('prodmark','keep-me');const r=await navigator.serviceWorker.getRegistrations();return{regs:r.map(x=>x.scope),caches:await caches.keys()}}""")
    c('L0 production page (as hosted at /become-studio/) registers its Service Worker and Cache Storage',len(prod['regs'])==1 and prod['regs'][0].endswith('/become-studio/') and any(k.startswith('bs-') for k in prod['caches']),prod)
    pg2=ctx.new_page();pg2.on('pageerror',lambda e:errs.append(str(e)))
    pg2.goto(B8766+'become-studio-lab/exp/cinematic-pro/index.html#res=360');ready(pg2);pg2.wait_for_timeout(1500)
    lab=pg2.evaluate("""async()=>({ctrl:!!navigator.serviceWorker.controller,regs:(await navigator.serviceWorker.getRegistrations()).map(x=>x.scope),caches:await caches.keys(),ns:CP.NS,title:document.title})""")
    c('L1 lab page is NOT controlled by the production Service Worker (scope /become-studio/ does not cover /become-studio-lab/)',lab['ctrl']==False and all(s.endswith('/become-studio/') for s in lab['regs']),lab)
    c('L2 lab page registers no Service Worker and creates no Cache Storage entries; namespace t_',lab['ns']=='t_' and lab['caches']==prod['caches'],lab)
    pg2.fill('#dsc','lab work');pg2.evaluate("async()=>{await CP.pjSave(true)}");pg2.wait_for_timeout(600)
    dbs=pg2.evaluate("async()=>(await indexedDB.databases()).map(d=>d.name)")
    c('L3 lab data lives only in t_-prefixed databases; no unprefixed cp_* database created',any(d=='t_cp_project' for d in dbs) and not any(d.startswith('cp_') for d in dbs),dbs)
    pg.reload();pg.wait_for_timeout(1500)
    after=pg.evaluate("""async()=>({mark:localStorage.getItem('prodmark'),regs:(await navigator.serviceWorker.getRegistrations()).length,caches:await caches.keys()})""")
    c('L4 after using the lab page, production localStorage, Service Worker and caches are unchanged',after['mark']=='keep-me' and after['regs']==1 and after['caches']==prod['caches'],after)
    c('L5 lab page shows the lab title; indexing-refusal meta present (not an access control)','試験' in lab['title'] and pg2.evaluate("()=>!!document.querySelector('meta[name=robots][content*=noindex]')"))
    c('Z no page errors',not errs,errs[:3]);print(sum(RR),'/',len(RR))
